// Offline battle royale simulation: a compact, procedural island and 23 rivals.
const canvas=$('#world'),ctx=canvas.getContext('2d');let W=0,H=0,raf=0,playing=false,player,bots=[],loot=[],keys={},camera={x:0,y:0},last=0,elapsed=0,kills=0,remaining=24,zone={x:1200,y:800,r:740},modeScale=1,mouse={x:0,y:0,down:false},touch={x:0,y:0,active:false},gameOver=false;
const rand=(a,b)=>a+Math.random()*(b-a),clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function resizeGame(){const r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=r.width*d;canvas.height=r.height*d;W=r.width;H=r.height;ctx.setTransform(d,0,0,d,0,0)}new ResizeObserver(resizeGame).observe(canvas);
const districts=[['MILITARY BASE',390,330,'#5b7560'],['SNOW PEAK',1150,210,'#9bafa9'],['ANCIENT RUINS',1770,340,'#9a805c'],['SCHOOL',740,685,'#628b72'],['CENTRAL CITY',1230,750,'#64796b'],['RESIDENTIAL',480,1000,'#718b68'],['PORT',1980,980,'#657c70'],['FACTORY',1620,1120,'#777c68'],['FOREST',890,1260,'#526e58'],['DESERT',2080,420,'#a89468'],['LAKE',1190,1300,'#4e8d8a'],['DARK CAVE',1930,1400,'#454e52']];
let buildings=[],trees=[],roads=[];function makeIsland(){buildings=[];trees=[];roads=[];for(let i=0;i<11;i++){let d=districts[i];for(let j=0;j<(i===4?30:i===3?17:i===5?23:9);j++){let a=rand(0,7),r=rand(35,i===4?240:150);buildings.push({x:clamp(d[1]+Math.cos(a)*r,40,2360),y:clamp(d[2]+Math.sin(a)*r,40,1560),w:rand(22,52),h:rand(20,46),c:['#b5a589','#c3b39a','#85998a','#d2c8a9','#717f79'][Math.floor(rand(0,5))],roof:['#675d50','#626968','#8b6759','#7e887b'][Math.floor(rand(0,4))]})}}for(let i=0;i<320;i++)trees.push({x:rand(20,2380),y:rand(20,1580),r:rand(6,15),tone:Math.floor(rand(0,5))});roads=[[0,800,2400,800],[1200,0,1200,1600],[290,280,720,610],[1510,660,2010,1030],[580,1120,1050,1430]]}
makeIsland();
function startGame(){openTab('PLAY');$('#lobby').classList.add('hidden');$('#game').classList.remove('hidden');resizeGame();playing=true;gameOver=false;elapsed=0;kills=0;remaining=24;modeScale=mode==='SQUAD'?1.3:mode==='DUO'?1.12:1;player={x:rand(1010,1400),y:rand(620,880),hp:100,armor:60,speed:210,angle:0,ammo:30,mag:30,reload:0,alive:true,fireCd:0};bots=Array.from({length:23},(_,i)=>({id:i,x:rand(120,2280),y:rand(90,1510),hp:100,armor:rand(10,65),speed:rand(55,95),angle:rand(0,6.28),think:rand(0,2),fire:rand(.4,2),alive:true,color:['#e98168','#d8cc78','#83bfaa','#8ca8df','#dc91b6'][i%5]}));loot=Array.from({length:60},()=>({x:rand(50,2350),y:rand(50,1550),type:['ammo','med','armor'][Math.floor(rand(0,3))],taken:false}));camera.x=player.x;camera.y=player.y;$('#gameUI').innerHTML=`<div class="hudtop"><div class="hudbox healthbox"><b>◈ ${mode} OPERATIVE</b><div class="bar"><i id="hpbar"></i></div><div class="bar armorbar"><i id="armorbar"></i></div><small id="hptext">100 HP · 60 ARMOR</small></div><div class="hudcenter"><strong id="alive">24</strong><br><small>OPERATORS LEFT</small></div><div class="hudbox weaponhud"><b>⌖ BREAKWATER AR</b><br><small><span id="ammotext">30</span> / 120 &nbsp; • &nbsp; AUTO</small></div></div><div class="mapbox"><canvas id="minimap"></canvas></div><div class="bottomhud"><div class="itemhud">⌖ <strong id="killcount">0</strong><br><small>ELIMS</small></div><div class="itemhud">✚ <strong id="medcount">2</strong><br><small>MEDKITS</small></div><div class="itemhud">◉ <strong>ZONE</strong><br><small id="zonetimer">02:00</small></div></div><div class="touch-controls"><div class="stick" id="stick"></div><button class="action" id="reload">RLD</button><button class="fire" id="fire">FIRE</button><div class="mobile-tip">DRAG TO MOVE · TAP FIRE TO ENGAGE</div></div><div id="result"></div>`;setupTouch();last=performance.now();cancelAnimationFrame(raf);raf=requestAnimationFrame(loop)}
$('#start').onclick=startGame;
function setupTouch(){let s=$('#stick');s.onpointerdown=e=>{s.setPointerCapture(e.pointerId);touch.active=true;touch.x=0;touch.y=0;stickMove(e)};s.onpointermove=e=>{if(touch.active)stickMove(e)};s.onpointerup=s.onpointercancel=()=>{touch.active=false;touch.x=touch.y=0};function stickMove(e){let b=s.getBoundingClientRect(),dx=e.clientX-(b.left+b.width/2),dy=e.clientY-(b.top+b.height/2),len=Math.hypot(dx,dy),max=39;touch.x=dx/Math.max(max,len);touch.y=dy/Math.max(max,len)}let f=$('#fire');f.onpointerdown=e=>{e.preventDefault();mouse.down=true};f.onpointerup=f.onpointercancel=()=>mouse.down=false;$('#reload').onclick=reload}
window.addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(e.key.toLowerCase()))e.preventDefault();if(e.key.toLowerCase()==='r')reload()});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);canvas.addEventListener('pointermove',e=>{let b=canvas.getBoundingClientRect();mouse.x=e.clientX-b.left;mouse.y=e.clientY-b.top});canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse')mouse.down=true});window.addEventListener('pointerup',e=>{if(e.pointerType==='mouse')mouse.down=false});
function reload(){if(player&&player.ammo<player.mag&&player.reload<=0&&player.alive)player.reload=1.1}
function nearestTarget(){let best=null,dist=620;for(let b of bots)if(b.alive){let d=Math.hypot(b.x-player.x,b.y-player.y);if(d<dist){dist=d;best=b}}return best}
