54:function openTab(tab){currentTab=tab;const modal=$('#modal');if(tab==='PLAY'){modal.classList.add('hidden');return}let title=tab,content='';if(tab==='OPERATORS'){title='OPERATORS / 50';content='<div class="catalog">'+names.map((n,i)=>`<div class="catalog-item"><span class="sigil">${['✦','◈','✧','❖','✺'][i%5]}</span><strong>${n.toUpperCase()}</strong><small class="${rarities[i%10]==='LEGENDARY'?'rank':''}">${rarities[i%10]} · ${i<25?'VANGUARD':'SPECIALIST'}</small></div>`).join('')+'</div>'}else if(tab==='ARSENAL'){title='ARSENAL / 50';content='<div class="catalog">'+weapons.map((n,i)=>`<div class="catalog-item"><span class="sigil">${['⌁','╱','⌖','⚡','◈'][i%5]}</span><strong>${n.toUpperCase()}</strong><small class="${i%10===9?'rank':''}">${['PISTOL','SMG','ASSAULT','SNIPER','SHOTGUN'][i%5]} · ${['RARE','COMMON','EPIC','RARE','LEGENDARY'][i%5]}</small></div>`).join('')+'</div>'}else{const data={MISSIONS:['DAILY CONTRACTS','Complete 3 eliminations','Open 5 supply crates','Travel 1200m in a match'],PASS:['TIDELINE / SEASON 07','Progress 18 / 60','Next reward: Neon wake weapon wrap','Season ends in 18 days'],FRIENDS:['SQUAD UP','MiraV is in the lobby · Invite','RenK is online · Invite','See all friends →'],RANKED:['RANKED / SILVER II','Top 10 in 4 matches to promotion','Season peak: Gold IV','View leaderboard →'],SETTINGS:['GAME SETTINGS','Graphics · High','Audio · 80%','Controls · Customize'],MAIL:['INBOX / 3 NEW','Welcome to Tideline — Claim 250 gold','Season 07 launch reward — Claim','Daily login bonus — Claim']};content='<div style="display:grid;gap:10px">'+(data[tab]||['COMING SOON']).map((s,i)=>`<div class="catalog-item" style="min-height:48px;display:flex;align-items:center;gap:15px"><span class="sigil" style="font-size:15px">${i===0?'✦':'◈'}</span><strong style="font-size:11px">${s}</strong></div>`).join('')+'</div>'}modal.innerHTML=`<div class="modal-card"><div class="modal-head"><h2>${title}</h2><button class="close" onclick="openTab('PLAY')">×</button></div>${content}</div>`;modal.classList.remove('hidden')}
62:function startGame(){openTab('PLAY');$('#lobby').classList.add('hidden');$('#game').classList.remove('hidden');resizeGame();playing=true;gameOver=false;elapsed=0;kills=0;remaining=24;player={x:rand(1010,1400),y:rand(620,880),hp:100,armor:60,speed:210,angle:0,ammo:30,mag:30,reload:0,alive:true,fireCd:0};bots=Array.from({length:23},(_,i)=>({id:i,x:rand(120,2280),y:rand(90,1510),hp:100,armor:rand(10,65),speed:rand(55,95),angle:rand(0,6.28),think:rand(0,2),fire:rand(.4,2),alive:true,color:['#e98168','#d8cc78','#83bfaa','#8ca8df','#dc91b6'][i%5]}));loot=Array.from({length:60},()=>({x:rand(50,2350),y:rand(50,1550),type:['ammo','med','armor'][Math.floor(rand(0,3))],taken:false}));camera.x=player.x;camera.y=player.y;$('#gameUI').innerHTML=`<div class="hudtop"><div class="hudbox healthbox"><b>◈ ${mode} OPERATIVE</b><div class="bar"><i id="hpbar"></i></div><div class="bar armorbar"><i id="armorbar"></i></div><small id="hptext">100 HP · 60 ARMOR</small></div><div class="hudcenter"><strong id="alive">24</strong><br><small>OPERATORS LEFT</small></div><div class="hudbox weaponhud"><b>⌖ BREAKWATER AR</b><br><small><span id="ammotext">30</span> / 120 &nbsp; • &nbsp; AUTO</small></div></div><div class="mapbox"><canvas id="minimap"></canvas></div><div class="bottomhud"><div class="itemhud">⌖ <strong id="killcount">0</strong><br><small>ELIMS</small></div><div class="itemhud">✚ <strong id="medcount">2</strong><br><small>MEDKITS</small></div><div class="itemhud">◉ <strong>ZONE</strong><br><small id="zonetimer">02:00</small></div></div><div class="touch-controls"><div class="stick" id="stick"></div><button class="action" id="reload">RLD</button><button class="fire" id="fire">FIRE</button><div class="mobile-tip">DRAG TO MOVE · TAP FIRE TO ENGAGE</div></div><div id="result"></div>`;setupTouch();last=performance.now();cancelAnimationFrame(raf);raf=requestAnimationFrame(loop)}$('#start').onclick=startGame;
